class Logger:
    def log(self, msg):
        return f'LOG: {msg}'

class Silent:
    pass

def record(obj, msg):
    if hasattr(obj, 'log'):
        return obj.log(msg)
    return 'no logger'

print(record(Logger(), 'hi'))
print(record(Silent(), 'hi'))

